export const inlineScript = "\n  (function() {\n    const fileInput = document.getElementById('screenshot-input');\n    const dropTarget = document.getElementById('drop-target');\n    const uploadStage = document.getElementById('upload-stage');\n    const clearBtn = document.getElementById('clear-uploads');\n    const continueBtn = document.getElementById('continue-btn');\n\n    if (dropTarget && fileInput) {\n      dropTarget.addEventListener('click', () => fileInput.click());\n    }\n\n    if (fileInput) {\n      fileInput.addEventListener('change', () => {\n        if (fileInput.files && fileInput.files.length > 0) {\n          uploadStage.classList.remove('hidden');\n          uploadStage.classList.add('flex');\n        }\n      });\n    }\n\n    if (clearBtn) {\n      clearBtn.addEventListener('click', () => {\n        if (fileInput) fileInput.value = '';\n        uploadStage.classList.add('hidden');\n        uploadStage.classList.remove('flex');\n      });\n    }\n\n    // Interactive Preset Radio styling\n    const radios = document.querySelectorAll('input[name=\"scoring-preset\"]');\n    radios.forEach(radio => {\n      radio.addEventListener('change', (e) => {\n        radios.forEach(r => {\n          const parent = r.closest('label');\n          if (r.checked) {\n            parent.classList.remove('bg-surface-container-low');\n            parent.classList.add('bg-surface-container-high');\n            if (continueBtn) {\n              if (r.value === 'custom') {\n                continueBtn.innerHTML = '<span class=\"material-symbols-outlined text-[18px]\">auto_awesome</span><span>CONTINUE WITH SCREENSHOT</span>';\n              } else {\n                continueBtn.innerHTML = '<span class=\"material-symbols-outlined text-[18px]\">done</span><span>CONFIRM ' + r.value.toUpperCase().replace('-', ' ') + '</span>';\n              }\n            }\n          } else {\n            parent.classList.remove('bg-surface-container-high');\n            parent.classList.add('bg-surface-container-low');\n          }\n        });\n      });\n    });\n  })();\n";
